    const u14 = path.join(tmp, "proj-wp14-stuck");
    S.initProject(u14, ["core"], "pt");
    const uf14 = S.createFeature(u14, "Presa", ["core"]);
    fs.writeFileSync(path.join(uf14.dir, "tasks.md"), "- [ ] 1. a\n");
    const uLock14 = path.join(uf14.dir, ".lock");
