    const setStamp16 = (v) => { const f = path.join(o16, ".specs", "roadmap.json"); const rm = readJ(f); rm.meta.specVersion = v; fs.writeFileSync(f, JSON.stringify(rm, null, 2)); };
    setStamp16("1.12.1");
