    const sNoVerify = S.stopCheck(pIm, { message: "**Status:** DONE\nReport: .specs/auth/.execution/task-2-report.md", agent: "spec-implementer" });
    const sActiveIm = runHook(stopJs, { ...subPayload(doneReply), stop_hook_active: true });
