    S.initProject(dfPt, ["core"], "pt");
    const ptc = S.createFeature(dfPt, "Motor", ["core"], "", undefined, undefined, undefined, { flow: "design-first" });
    const ptna = S.nextAction(dfPt, ptc.slug);
