    const pB = path.join(tmp, "proj-f2-r1-broken"), pB2 = path.join(tmp, "proj-f2-r1-noguard"), pB3 = path.join(tmp, "proj-f2-r1-two"), pOffW = path.join(tmp, "proj-f2-r1-off");
