    const copies = [["demo", path.join(root, "examples", "demo-project"), null], ["specs-en", path.join(root, "evals", "fixtures", "specs-en"), ".specs"], ["specs-es", path.join(root, "evals", "fixtures", "specs-es"), ".specs"]];
